package com.posapp.invoice.dto;

import com.posapp.invoice.Invoice;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.List;

public record InvoiceDto(
        Long id,
        String invoiceNumber,
        Long salesOrderId,
        String salesOrderNumber,
        /** Fourier: "Subscriptions Module" — set only on an invoice auto-generated by the daily subscription billing sweep; see Invoice.subscriptionId's javadoc. */
        Long subscriptionId,
        /** Fourier: "Add Recurring Invoice" — set only on an invoice auto-generated by a recurring invoice template's sweep or manual "run now"; see Invoice.recurringInvoiceTemplateId's javadoc. */
        Long recurringInvoiceTemplateId,
        Long customerId,
        String customerName,
        /** Fourier: "sending ... invoices ... to the customer's email" — the customer's *current* email (looked up fresh by InvoiceService, not snapshotted on the Invoice itself), for the admin UI to pre-fill the "email this" prompt with. Null when this invoice has no customerId at all, or that customer has no email on file. */
        String customerEmail,
        String status,
        Instant invoiceDate,
        LocalDate dueDate,
        /** Fourier: "create an invoice from the last end date" — the billing cycle this invoice covers; null for a non-subscription invoice. See Invoice.periodStart's own javadoc. */
        LocalDate periodStart,
        LocalDate periodEnd,
        String notes,
        /** Fourier: "for purchases, sales, invoices, bills the tax are not being captured" — now tax-inclusive (subtotalAmount + taxAmount); was previously just the sum of every line's lineTotal, with no tax at all. */
        BigDecimal totalAmount,
        /** Sum of every line's pre-tax contribution — see InvoiceService.subtotalAmount. */
        BigDecimal subtotalAmount,
        /** Sum of every line's own tax — zero when no line has a tax rate assigned. See InvoiceService.taxAmount. */
        BigDecimal taxAmount,
        /** Fourier: "Same for discount ... it will be per line" — sum of every line's own discountAmount, purely informational (already folded into subtotalAmount/totalAmount above). Zero whenever the feature is off or no line has one. */
        BigDecimal discountAmount,
        /** Fourier: "Except POS other module can have global discount ... Either on line or global" — the single discount percentage entered for the whole invoice (GLOBAL mode only, or carried verbatim from the originating Sales Order — see Invoice.discountPercent's javadoc). Zero when discount was entered per line instead, or not at all. */
        BigDecimal discountPercent,
        /** Fourier: "Global discount should be a fixed amount or percentage with percentage as the default" — how discountPercent above was entered; see Invoice.discountType's javadoc. */
        String discountType,
        /** The flat currency amount actually typed, when discountType is FIXED_AMOUNT; null otherwise. See Invoice.discountFixedAmount's javadoc. */
        BigDecimal discountFixedAmount,
        List<InvoiceLineDto> lines,
        Instant voidedAt,
        String voidReason,
        /** Fourier: "Add credit note Menu (Void) Where we can printout them" — null until this invoice is voided; see Invoice.creditNoteNumber's javadoc. */
        String creditNoteNumber,
        /** Fourier: "CANCEL/CREDIT PAID INVOICE ... Refund OR Customer Credit" — null unless this was voided via InvoiceService.cancelPaidInvoice; see Invoice.paymentDisposition's javadoc. */
        String paymentDisposition,
        /** Only set when paymentDisposition is REFUND — see Invoice.refundMethod's javadoc. */
        String refundMethod,
        /** Fourier: "record payment on invoice" — zero for a DRAFT/VOID invoice (see the backend CustomerCreditService.amountPaidForInvoice/outstandingForInvoice's own javadoc); only an ISSUED invoice is ever payable. */
        BigDecimal amountPaid,
        BigDecimal amountOutstanding,
        /** The branch this invoice belongs to; null on legacy rows (= head office). */
        Long branchId
) {
    public static InvoiceDto from(Invoice inv, String customerEmail, BigDecimal amountPaid, BigDecimal amountOutstanding,
                                   BigDecimal subtotalAmount, BigDecimal taxAmount, BigDecimal discountAmount) {
        return new InvoiceDto(
                inv.getId(),
                inv.getInvoiceNumber(),
                inv.getSalesOrderId(),
                inv.getSalesOrderNumber(),
                inv.getSubscriptionId(),
                inv.getRecurringInvoiceTemplateId(),
                inv.getCustomerId(),
                inv.getCustomerName(),
                customerEmail,
                inv.getStatus().name(),
                inv.getInvoiceDate(),
                inv.getDueDate(),
                inv.getPeriodStart(),
                inv.getPeriodEnd(),
                inv.getNotes(),
                inv.getTotalAmount(),
                subtotalAmount,
                taxAmount,
                discountAmount,
                inv.getDiscountPercent(),
                inv.getDiscountType() != null ? inv.getDiscountType().name() : null,
                inv.getDiscountFixedAmount(),
                inv.getLines().stream().map(InvoiceLineDto::from).toList(),
                inv.getVoidedAt(),
                inv.getVoidReason(),
                inv.getCreditNoteNumber(),
                inv.getPaymentDisposition() != null ? inv.getPaymentDisposition().name() : null,
                inv.getRefundMethod(),
                amountPaid,
                amountOutstanding,
                inv.getBranchId()
        );
    }
}
